/// Calculates estimated radiation dose (in mSv) for a given activity and duration.\n///\n/// * `activity` – one of "resting", "moderate", or "heavy".\n/// * `hours` – time spent in hours (may be fractional).\n///\n/// Returns `Ok(dose)` on success or `Err(&str)` if the activity is unknown.\npub fn calculate_dose(activity: &str, hours: f64) -> Result<f64, &'static str> {\n    if hours < 0.0 {\n        return Err("hours cannot be negative");\n    }\n    let rate = match activity {\n        "resting" => 0.01,\n        "moderate" => 0.05,\n        "heavy" => 0.20,\n        _ => return Err("unknown activity"),\n    };\n    Ok(rate * hours)\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn test_resting() {\n        let dose = calculate_dose("resting", 5.0).unwrap();\n        assert!((dose - 0.05).abs() < 1e-6);\n    }\n\n    #[test]\n    fn test_moderate() {\n        let dose = calculate_dose("moderate", 2.0).unwrap();\n        assert!((dose - 0.10).abs() < 1e-6);\n    }\n\n    #[test]\n    fn test_heavy() {\n        let dose = calculate_dose("heavy", 1.5).unwrap();\n        assert!((dose - 0.30).abs() < 1e-6);\n    }\n\n    #[test]\n    fn test_unknown_activity() {\n        let err = calculate_dose("unknown", 1.0).unwrap_err();\n        assert_eq!(err, "unknown activity");\n    }\n\n    #[test]\n    fn test_negative_hours() {\n        let err = calculate_dose("resting", -1.0).unwrap_err();\n        assert_eq!(err, "hours cannot be negative");\n    }\n}\n
